#!/usr/bin/env python3
"""Write docs/runtimes-pallets.md from the runtimes' own construct_runtime! blocks.

The file it replaces was written by hand on 2025-12-08 and then left alone. Ten months later it
still listed `pallet_staking` on the relay, a validator pool that had been removed, and an Asset
Hub of 43 pallets that had grown to 51 -- an inventory that was confidently wrong is worse than
none, because it is the one place a reader would look and stop looking. So the inventory is now
derived, and `--check` turns red the moment the code moves without it.

Usage:
  runtime-pallets.py           rewrite docs/runtimes-pallets.md
  runtime-pallets.py --check   exit 1 if the file differs from what the code says
"""

import importlib.util
import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
OUT = REPO / "docs" / "runtimes-pallets.md"

# Reuse the parser the pallet-index gate already trusts, so the two cannot disagree about what
# a construct_runtime! block contains.
_spec = importlib.util.spec_from_file_location("pallet_indices", REPO / ".github/scripts/check-pallet-indices.py")
pallet_indices = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(pallet_indices)

# `Name: path::to::pallet = 12,` -- the same shape ENTRY matches, with the path kept.
ENTRY = re.compile(r"^\s*(\w+)\s*:\s*([\w:<>]+)\s*=\s*(\d+)\s*,", re.M)
SPEC_NAME = re.compile(r'spec_name:\s*[\w:]*\(?\s*"([^"]+)"')
SPEC_VERSION = re.compile(r"spec_version:\s*([\d_]+)")

# Twins that must match pallet for pallet, except where check-twin-runtimes.py records why not.
TWINS = [
    ("relay", "pezkuwichain", "zagros"),
    ("Asset Hub", "asset-hub-pezkuwichain", "asset-hub-zagros"),
    ("People", "people-pezkuwichain", "people-zagros"),
]


def pallets(lib: Path):
    text = lib.read_text(errors="replace")
    m = pallet_indices.MACRO.search(text)
    if not m:
        return None
    end = text.find("\n}", m.end())
    body = text[m.end() : end if end != -1 else len(text)]
    rows = [(int(idx), name, path) for name, path, idx in ENTRY.findall(body)]
    return sorted(rows) or None


def render():
    runtimes = {}
    for pattern in pallet_indices.RUNTIME_GLOBS:
        for lib in sorted(REPO.glob(pattern)):
            rows = pallets(lib)
            if not rows:
                continue
            text = lib.read_text(errors="replace")
            name = SPEC_NAME.search(text)
            version = SPEC_VERSION.search(text)
            runtimes[lib.parts[-3]] = {
                "path": lib.relative_to(REPO).as_posix(),
                "spec_name": name.group(1) if name else "?",
                "spec_version": version.group(1) if version else "?",
                "rows": rows,
            }
    if not runtimes:
        sys.exit("no construct_runtime! blocks found -- the parser went blind")

    out = [
        "# Runtime pallets",
        "",
        "<!-- Generated by .github/scripts/runtime-pallets.py from each runtime's construct_runtime!.",
        "     Do not edit by hand: run the script. The pre-commit hook and CI run it with --check. -->",
        "",
        "Every pallet in every runtime of this tree, by index, as `construct_runtime!` declares it.",
        "Mainnet launches with the relay, Asset Hub and People runtimes named `pezkuwichain`; Zagros",
        "runs their twins and, ahead of mainnet, Bridge Hub, Coretime and Collectives.",
        "",
        "## Twins",
        "",
        "Pallets present on one twin only. Each must be recorded with its reason in",
        "`.github/scripts/check-twin-runtimes.py`, which fails on any that is not.",
        "",
        "| twins | mainnet only | Zagros only |",
        "|---|---|---|",
    ]
    for label, main, test in TWINS:
        if main not in runtimes or test not in runtimes:
            continue
        a = {n for _, n, _ in runtimes[main]["rows"]}
        b = {n for _, n, _ in runtimes[test]["rows"]}
        only_a = ", ".join(sorted(a - b)) or "—"
        only_b = ", ".join(sorted(b - a)) or "—"
        out.append(f"| {label} | {only_a} | {only_b} |")
    out.append("")

    for key in sorted(runtimes):
        r = runtimes[key]
        out += [
            f"## {key}",
            "",
            f"`{r['path']}` · spec `{r['spec_name']}` {r['spec_version']} · {len(r['rows'])} pallets",
            "",
            "| index | pallet | crate |",
            "|---:|---|---|",
        ]
        out += [f"| {idx} | {name} | `{path}` |" for idx, name, path in r["rows"]]
        out.append("")
    return "\n".join(out)


def main():
    text = render()
    if "--check" in sys.argv:
        current = OUT.read_text() if OUT.exists() else ""
        if current != text:
            print(f"{OUT.relative_to(REPO)} is stale: run python3 .github/scripts/runtime-pallets.py")
            return 1
        print(f"{OUT.relative_to(REPO)} matches the runtimes")
        return 0
    OUT.write_text(text)
    print(f"wrote {OUT.relative_to(REPO)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
